import { BrowserRouter, Routes, Route, Link, useParams } from 'react-router';

const daftar = [
  { id: 1, nama: 'Kopi Susu', harga: 15000 },
  { id: 2, nama: 'Teh Melati', harga: 8000 },
];

function DaftarProduk() {
  return (
    <ul>
      {daftar.map((p) => (
        <li key={p.id}><Link to={`/produk/${p.id}`}>{p.nama}</Link></li>
      ))}
      <li><Link to="/produk/99">Produk nomor 99</Link></li>
    </ul>
  );
}

function DetailProduk() {
  const { id } = useParams();
  const produk = daftar.find((p) => p.id === Number(id));
  if (!produk) return <p>Produk tidak ditemukan. <Link to="/">← Kembali</Link></p>;
  return (
    <div>
      <h2>{produk.nama}</h2>
      <p>Rp{produk.harga.toLocaleString('id-ID')}</p>
      <Link to="/">← Kembali</Link>
    </div>
  );
}

export default function App() {
  return (
    <BrowserRouter>
      <Routes>
        <Route path="/" element={<DaftarProduk />} />
        <Route path="/produk/:id" element={<DetailProduk />} />
      </Routes>
    </BrowserRouter>
  );
}
